import{z as l,x as s,o as e,c as o,q as A,j as B,D as E,d as t,s as n,S as i}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"指数套利","description":"","frontmatter":{"title":"指数套利","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/index-arb.md","filePath":"quant/index-arb.md","lastUpdated":1791063341000}'),d={name:"quant/index-arb.md"};function p(m,a,h,u,F,D){const r=s("Mermaid");return e(),o("div",null,[a[2]||(a[2]=A('<h1 id="指数套利" tabindex="-1">指数套利 <a class="header-anchor" href="#指数套利" aria-label="Permalink to &quot;指数套利&quot;">​</a></h1><div class="epigraph"><p>指数期货与现货一揽子之间的基差，受持有成本、提前行权式的随机股利与交易摩擦约束；偏离在足够大时触发期现对锁，但程序化买卖本身会在现货端留下冲击与日内波动。</p><footer>—— MacKinlay &amp; Ramaswamy, Index-Futures Arbitrage and the Behavior of Stock Index Futures Prices, Review of Financial Studies, 1988</footer></div><p><a href="/quant/residual-momentum">上一课</a>用因子回归残差的 12−1 累计排序，试图保留特异相对强度；残差不可直接买卖，中性是否成立取决于窗口与因子选择。那是统计溢价，没有到期强制收敛。缺口是制度上最近似「有收敛日期的相对价值」：期货以指数结算，现货一揽子可以复制指数，基差写成持有成本加减一条由摩擦决定的无套利带。带内偏离不是免费午餐；带外面对一揽子同时成交、涨跌停、股利预测与保证金。本课写这条指数套利。不重讲残差动量的换手。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>持有成本理论给出期货公允价格</p> \\[F_{t,T}=S_t e^{(r-d)(T-t)} \\]<p>（连续近似），\\(S\\) 为现货指数，\\(d\\) 为红利率。真实市场有买卖价差、股票无法同时成交、指数是报价而非可买的资产、股利路径不确定、期货有保证金与基差风险（对提前平仓）。于是无套利不是一条线，而是一条带。问题是：观测到的 \\(F-S\\) 有多少是带内噪声（Miller、Muthuswamy、Whaley 讨论过基差变化的均值回归可能来自非同步报价），有多少是可执行的错误定价。</p><p><span class="marginnote">数字实例：指数 4000 点、融资利率 3%、股利率 2%、距到期 3 个月，公允价约 \\(F=4000\\times e^{(0.03-0.02)\\times0.25}\\approx4010\\) 点。期货报到 4030 点且超出成本半宽，正向套利（买现货、卖期货）才值得做；带内的 5 点偏离只是噪声。</span></p><p>现货指数包含滞后交易的股票，期货几乎连续。期货相对「陈旧」的指数升水或贴水，很大一块是伪基差。用这个伪基差去下程序化单，等于在交易非同步，而不是交易收敛。MacKinlay–Ramaswamy 强调把可交易一揽子与指数本身分开，并允许套利资本有限，从而基差可以在带内随机游走一段。</p><h3 id="无套利带与提早平仓" tabindex="-1">无套利带与提早平仓 <a class="header-anchor" href="#无套利带与提早平仓" aria-label="Permalink to &quot;无套利带与提早平仓&quot;">​</a></h3><p>Brennan–Schwartz 允许套利者在到期前平仓，于是策略像一个有界过程的最优进出，而不是持有到 \\(T\\)。这改变了「偏离多大才开仓」：太大的偏离可能很快回来，但回来的路径依赖其他人的程序化单。带的宽度由一揽子的有效价差、冲击、借券与期货手续费共同决定。宽度随市场压力变：1987、2010 闪电崩盘、以及涨跌停制度下，带可以突然变宽，旧阈值会在不可成交的价格上触发。</p><p><span class="marginnote">「无套利带」就是把教科书里的一条无套利等式加粗成一条区间：中心是持有成本公允价，半宽是往返交易成本。基差在带内晃是常态——这时下单等于白送手续费；出了带才谈得上有利可图。</span></p><p><span class="marginnote">指数本身通常不能买。套利的现货腿是一揽子股票或 ETF。用指数点位算「套利利润」却用一揽子成交，会把跟踪误差当成 alpha。规格必须写清复制误差的预算。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>可复制的检查单。第一，定义可交易现货：全市场一揽子、分层抽样、或指数 ETF。第二，把期货与现货对齐到同一时钟，处理到期滚动。第三，估计持有成本：\\(r\\) 用融资利率而非无风险国债，\\(d\\) 用预测股利而非事后实现股利——事后 \\(d\\) 会制造前视。第四，把往返成本加进带的半宽：股票有效价差之和（按权重）、期货有效价差、冲击（Kyle 型或 Almgren–Chriss 轨迹）、以及失败成交的惩罚。第五，只有当 \\(|F-S_{\\mathrm{basket}}e^{(r-d)\\tau}|\\) 超出半宽才允许下单，并假设部分成交。</p><p>Sofianos 用实际套利账户的数据说明：许多表面上的偏离在可执行价格下并不盈利；盈利集中在波动高、带被打穿的短窗口。Stoll 与 Whaley 从指数与期货收益的领先滞后描述信息传递：期货往往领先，套利是把这一领先翻译成现货成交。工程上这要求现货腿能在秒到分钟级完成，否则你锁的是已经收敛了一半的基差。</p><h3 id="程序化交易、涨跌停与结算" tabindex="-1">程序化交易、涨跌停与结算 <a class="header-anchor" href="#程序化交易、涨跌停与结算" aria-label="Permalink to &quot;程序化交易、涨跌停与结算&quot;">​</a></h3><p>到期日与开盘、收盘集合竞价是基差与操纵风险的集中地。结算价若用特定窗口的现货，期货空头与现货多头的对锁要在那一窗口对齐，否则留下方向性残差。涨跌停使一揽子缺腿：缺的往往是最该成交的名字，复制误差在你最需要收敛时最大。A 股与部分亚洲市场的期现制度、保证金、套保额度，会把理论上的带变成监管约束下的更宽带。没有额度时，「套利」退化成单边期货或单边 ETF，那是方向性交易。</p><p><span class="marginnote">Harris–Sofianos–Shapiro（1994）讨论程序化交易与日内波动的关联。波动升高既可能是套利把信息写入价格，也可能是一揽子冲击。把「指数套利降低效率」或「提高效率」写成单一符号，忽略了窗口与冲击的尺度。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>收敛机制是合约结算与可复制性，不是协整检验给出的统计回归。只要到期用现货结算且一揽子可买，基差在 \\(T\\) 被强制对齐（指数定义与可买一揽子仍有差别）。此前的回归来自套利资本的进入。资本有限或融资紧张时，基差可以长时间停在带外，看起来像 OU，其实是约束下的缺口。这与股票配对的关键差别：配对没有到期强制对齐。</p><p>领先滞后：信息先到期货，套利买（卖）现货、卖（买）期货，现货被「追上」。若现货因涨跌停追不上，期货基差扩大，套利者面临追保与无法对锁。此时继续按旧带去加仓，是在交易流动性枯竭，不是在交易持有成本。Miller 等人提醒：用非同步的指数水平算基差均值回归，会把陈旧报价的更新误写成套利机会。</p>',22)),(e(),B(i,null,{default:E(()=>[n(r,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20LEAD%5B%22%E4%BF%A1%E6%81%AF%E5%85%88%E5%88%B0%E6%9C%9F%E8%B4%A7%3A%20%E5%9F%BA%E5%B7%AE%E5%81%8F%E7%A6%BB%E5%85%AC%E5%85%81%22%5D%20--%3E%20PATH%7B%22%E7%8E%B0%E8%B4%A7%E8%85%BF%E8%83%BD%E5%90%A6%E6%88%90%E4%BA%A4%22%7D%0A%20%20PATH%20--%3E%7C%22%E8%83%BD%22%7C%20CATCH%5B%22%E7%A8%8B%E5%BA%8F%E5%8C%96%E4%B9%B0%E7%8E%B0%E8%B4%A7%E5%8D%96%E6%9C%9F%E8%B4%A7%3A%20%E7%8E%B0%E8%B4%A7%E8%A2%AB%E8%BF%BD%E4%B8%8A%22%5D%0A%20%20CATCH%20--%3E%20BACK%5B%22%E5%9F%BA%E5%B7%AE%E5%9B%9E%E5%B8%A6%E5%86%85%20%2F%20%E5%88%B0%E6%9C%9F%E5%BC%BA%E5%88%B6%E5%AF%B9%E9%BD%90%22%5D%0A%20%20PATH%20--%3E%7C%22%E6%B6%A8%E8%B7%8C%E5%81%9C%2C%20%E4%B8%8D%E8%83%BD%22%7C%20WIDE%5B%22%E5%A4%8D%E5%88%B6%E7%BC%BA%E8%85%BF%3A%20%E5%9F%BA%E5%B7%AE%E7%BB%A7%E7%BB%AD%E6%89%A9%E5%A4%A7%22%5D%0A%20%20WIDE%20--%3E%20MARGIN%5B%22%E8%BF%BD%E4%BF%9D%E5%8E%8B%E5%8A%9B%20%2B%20%E6%97%A0%E6%B3%95%E5%AF%B9%E9%94%81%22%5D%0A%20%20MARGIN%20--%3E%20TRAP%5B%22%E6%8C%89%E6%97%A7%E5%B8%A6%E5%8A%A0%E4%BB%93%20%3D%20%E4%BA%A4%E6%98%93%E6%B5%81%E5%8A%A8%E6%80%A7%E6%9E%AF%E7%AB%AD%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A('<h3 id="容量、拥挤与「人人都是套利者」" tabindex="-1">容量、拥挤与「人人都是套利者」 <a class="header-anchor" href="#容量、拥挤与「人人都是套利者」" aria-label="Permalink to &quot;容量、拥挤与「人人都是套利者」&quot;">​</a></h3><p>指数套利的容量表面上由指数成分的 ADV 决定，实际上由同时想锁同一偏离的资本决定。偏离一旦被彭博或交易终端的「公平价值」栏目标出，竞争使可执行边缘降到带的边界。大账户必须拆单，执行时间拉长，基差在执行中收敛，实现利润小于信号利润——这是 Perold 实施缺口在期现上的版本。期货流动性通常好于一揽子里最差的成分股，瓶颈永远在现货腿。</p><p><span class="marginnote">初学者容易以为指数套利的容量看期货持仓量。瓶颈其实在现货腿：一揽子里流动性最差的成分股决定你能多快建仓。期货那一腿通常很深，但两条腿只有一条深，不叫对锁。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>股利预测、融券与公司行为会在除权日附近制造假偏离。指数调整日现货一揽子与期货标的短暂不一致。用 ETF 代替一揽子会把问题变成<a href="/quant/etf-arb">ETF 与成分股</a>：申赎机制不同、追踪误差不同。成本必须用有效价差与部分成交，不能用指数点差的一半。</p><p>不要把基差的样本内 OU 半衰期写成保证利润：半衰期估的是包含伪基差与拥挤交易的混合物。策略应报告：带内交易的负期望（你在付价差）、带外交易的条件期望、执行成功率、以及现货跟踪误差。若跟踪误差的波动大于基差本身，所谓套利是带杠杆的指数增强，风险预算应按方向性仓位计。</p><p><span class="marginnote">持有成本模型里的 \\(r\\) 在压力期应换成实际融资与保证金利率。用国债利率算「巨大贴水」，常常只是在描述信贷与期货保证金，而不是可锁的套利。</span></p>',7)),(e(),B(i,null,{default:E(()=>[n(r,{id:"mermaid-84",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%8F%AF%E4%BA%A4%E6%98%93%E4%B8%80%E6%8F%BD%E5%AD%90%20S%22%5D%20--%3E%20FV%5B%22%E6%8C%81%E6%9C%89%E6%88%90%E6%9C%AC%E5%85%AC%E5%B9%B3%E4%BB%B7%E5%80%BC%22%5D%0A%20%20R%5B%22%E8%9E%8D%E8%B5%84%20r%20%E4%B8%8E%E8%82%A1%E5%88%A9%20d%22%5D%20--%3E%20FV%0A%20%20FV%20--%3E%20BAND%5B%22%E6%91%A9%E6%93%A6%E5%86%B3%E5%AE%9A%E7%9A%84%E6%97%A0%E5%A5%97%E5%88%A9%E5%B8%A6%22%5D%0A%20%20FUT%5B%22%E6%8C%87%E6%95%B0%E6%9C%9F%E8%B4%A7%20F%22%5D%20--%3E%20BAS%5B%22%E5%9F%BA%E5%B7%AE%20F%20-%20FV%22%5D%0A%20%20BAS%20--%3E%20BAND%0A%20%20BAND%20--%3E%7C%22%E5%B8%A6%E5%A4%96%E4%B8%94%E5%8F%AF%E5%90%8C%E6%97%B6%E6%88%90%E4%BA%A4%22%7C%20ARB%5B%22%E6%9C%9F%E7%8E%B0%E5%AF%B9%E9%94%81%22%5D%0A%20%20ARB%20--%3E%20EXE%5B%22%E4%B8%80%E6%8F%BD%E5%AD%90%E5%86%B2%E5%87%BB%E4%B8%8E%E9%83%A8%E5%88%86%E6%88%90%E4%BA%A4%22%5D%0A%20%20EXE%20--%3E%20PNL%5B%22%E6%89%A3%E8%B4%B9%E5%90%8E%E5%87%80%E5%9F%BA%E5%B7%AE%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=A('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>指数套利依赖结算与可复制一揽子，无套利是一条由摩擦决定的带，不是持有成本等式上的一个点。</li><li>伪基差来自非同步报价；MacKinlay–Ramaswamy、Miller–Muthuswamy–Whaley 要求把可交易现货与指数点位分开。</li><li>可执行利润远小于报价偏离；Sofianos 与程序化交易文献强调冲击、部分成交与日内波动。</li><li>容量瓶颈在现货腿与拥挤执行；融资与涨跌停会突然加宽带宽。</li><li>出处：MacKinlay and Ramaswamy, <em>Review of Financial Studies</em>, 1988；Modest and Sundaresan, <em>Journal of Futures Markets</em>, 1983；Brennan and Schwartz, <em>Journal of Business</em>, 1990；Stoll and Whaley, <em>JFQA</em>, 1990；Sofianos, <em>Journal of Derivatives</em>, 1993；Harris, Sofianos and Shapiro, <em>RFS</em>, 1994。</li></ul>',2))])}const C=l(d,[["render",p]]);export{_ as __pageData,C as default};
